INSERT INTO `reports` VALUES (124,'Security audit · 9 Nov 2026','Security audit','running',0,'Denis Mehmed','2026-11-09 15:26:10',0);
INSERT INTO `reports` VALUES (125,'Security audit · 9 Nov 2026','Security audit','running',0,'Denis Mehmed','2026-11-09 15:37:24',0);
INSERT INTO `test_log` VALUES (1,'UI-001','2026-11-09','Interface','Every page loads without errors','pass','PHP syntax check on every file, then an HTTP request to each page as a signed-in admin: all returned 200 with no PHP warnings or notices in the output or the error log.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (2,'UI-002','2026-11-09','Interface','Phone layout (390 px wide)','pass','Overview, tables and forms render without horizontal scrolling (0 px overflow). The hamburger button opens the menu as a drawer.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (3,'UI-003','2026-11-09','Interface','Dark mode and Telecomlijn branding','pass','Login, overview, users and settings pages inspected in screenshots at 1440 px. Logo, palette (navy, lime, butter) and the self-hosted font render as designed.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (4,'UI-004','2026-11-09','Interface','Buttons on a lime background are readable','fixed','The owner reported that the \"Show all sessions\" button had white text on lime. The same missing text colour affected the matching buttons on Users, Reports and Logs, and the keyboard skip-link. After the fix every lime button on six pages was measured: all use dark navy text.','Added the dark text colour to the four empty-state buttons and to the skip-link.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (5,'UI-005','2026-11-09','Interface','Overview with an empty database','fixed','After the demo data was removed the overview said \"0 of 0 services healthy\" and showed an empty ribbon panel.','Added an empty state (\"Nothing is tracked yet\", with an Add an endpoint button) and made the demo-data warnings appear only when demo data is loaded.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (6,'UI-006','2026-11-09','Interface','Pop-out sidebar and pin button','pass','Hidden at first; moving to the left edge opens it; leaving closes it; pinning keeps it open, survives a reload and shifts the content to 256 px; the [ key toggles the pin; the phone drawer still works.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (7,'UI-007','2026-11-09','Interface','Menu control is easy to find','pass','Fresh browser profile: the lime Menu button and the edge tab are visible and the tab nudges a few times. After the menu has been opened once the nudge stops. Pinning hides both controls.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (8,'UI-008','2026-11-09','Interface','Easter egg: typing \"creator\" in the search bar','fixed','The button appears for \"creator\" and \"CREATOR \", not for \"creators\"; Enter moves focus to the button instead of searching; clicking opens the credits page; logged-out visitors are sent to the login page. Two defects were found while building it: a parse error caused by a mangled variable name, and two H1 headings on the page.','Restored the variable name; the layout title is hidden on that page so it has one heading.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (9,'UI-009','2026-11-09','Interface','Page layout while the sidebar is pinned','pass','Measured in a real window: content starts at 256 px, exactly the sidebar width. An earlier cropped full-page screenshot was a capture artefact, not a layout bug.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (10,'ANI-001','2026-11-09','Animation','Motion system behaves as designed','pass','Numbers count up, the sidebar pill moves on hover and remembers its place between pages, the tooltip follows the cursor, a row slides away before Terminate submits, and the confirmation toast leaves after about five seconds.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (11,'ANI-002','2026-11-09','Animation','Count-up never shows a wrong number','fixed','A service uptime briefly showed -3.6 percent in the first frame, because the animation clock was slightly earlier than the recorded start time.','Progress is now clamped between 0 and 1.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (12,'ANI-003','2026-11-09','Animation','Reduced-motion setting','pass','With prefers-reduced-motion on, numbers show their final value immediately and no content stays hidden.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (13,'ANI-004','2026-11-09','Animation','Design detector advisory','info','The Impeccable detector flags the springy easing curve as a bounce advisory. It is kept on purpose because the Disney animation principles were requested.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (14,'LANG-001','2026-11-09','Language toggle','Translation to Dutch','pass','Choosing Dutch translated the heading and sidebar (\"Overzicht\", \"Gebruikers\"), the choice carried over to other pages, and choosing English restored the original.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (15,'LANG-002','2026-11-09','Language toggle','Compatibility with the Content-Security-Policy','fixed','With the strict policy in place Google Translate was blocked from one host and from framing itself.','Allowed translate-pa.googleapis.com and same-origin frames. Only a harmless tracking pixel over plain http remains blocked.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (16,'AUTH-001','2026-11-09','Authentication','Enter key on the login form','pass','Enter in the username field moves focus to the password field without reloading; Enter on an empty password stays put; Enter with both filled signs in.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (17,'AUTH-002','2026-11-09','Authentication','Brute-force lockout','pass','Six wrong passwords in a row: the sixth attempt was refused. A fresh browser with no cookies and the correct password was still refused, so the limit is stored per address, not in the session.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (18,'AUTH-003','2026-11-09','Authentication','Forced password change','pass','A temporary password redirected every page to the change-password form. The passwords \"short1\", \"admin\" and \"adminadminadmin\" were rejected; a valid 12+ character password was accepted. Later the owner chose to keep admin/admin without a forced change for the admin account; other accounts still must change theirs.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (19,'AUTH-004','2026-11-09','Authentication','admin/admin signs straight in','pass','After the owner request: login returns 302 to the dashboard and the dashboard returns 200. The demo hint on the login page shows only while the password is still admin.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (20,'AUTH-005','2026-11-09','Authentication','Session cookie flags','pass','HttpOnly and SameSite=Lax observed. The Secure flag and the __Host- prefix switch on under HTTPS, which cannot be tested on localhost.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (21,'AC-001','2026-11-09','Access control','Pages require a login','pass','Every page, the CSV download and the invoice pages redirect a visitor without a session to the login page.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (22,'AC-002','2026-11-09','Access control','Permission levels for normal users','pass','No access: 403 on the Integrations, Team and Privacy pages and on forged POST requests, and no account was created by a forged request. View only: tab visible, no add/edit/delete buttons, forged add and key creation 403, running a check allowed. Can manage: adding an endpoint works, the Team tab stays 403. Taking the permission away took effect on the next click.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (23,'AC-003','2026-11-09','Access control','Team safeguards','pass','The only admin cannot demote or disable themselves; disabling an account signs that person out immediately; a duplicate username is rejected; a new person must change their temporary password.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (24,'AC-004','2026-11-09','Access control','Audit trail of access events','pass','Access denied, Access changed, CSRF check failed, Team member added and Account disabled/enabled all appear in the activity log with the actor.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (25,'AC-005','2026-11-09','Access control','Privacy requests are admin-only','pass','A normal user receives 403 for the Privacy requests page; admins can open it.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (26,'SEC-001','2026-11-09','Security','Database account privileges','fixed','The app connected to MariaDB as root with no password.','Created ops_console_app with SELECT, INSERT, UPDATE and DELETE on one database. Credentials live in the git-ignored includes/config.local.php. Verified with SHOW GRANTS.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (27,'SEC-002','2026-11-09','Security','Files that must not be public','fixed','PRODUCT.md, setup.php and the SQL schema could be read in a browser, and the assets folder listed its files.','Apache rules now return 403 for documents, SQL, logs, config and setup.php, and directory listing is off. All probes return 403.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (28,'SEC-003','2026-11-09','Security','Error messages do not leak internals','fixed','A request with an array parameter (?q[]=a&sort[]=x) produced a fatal error showing file paths.','Errors are logged to a private folder; visitors see a generic page with a reference code. The same request now returns a normal page with no error text.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (29,'SEC-004','2026-11-09','Security','Cross-site request forgery protection','fixed','A POST without a token was rejected, but with HTTP status 419, which Apache turned into a 500 error.','Status changed to 403. Every rejection is written to the activity log.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (30,'SEC-005','2026-11-09','Security','Forged redirect parameter','fixed','The back parameter on the users and connections actions was appended to the redirect address.','Only a short query string of safe characters is accepted; a forged value such as //evil.example/x is ignored.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (31,'SEC-006','2026-11-09','Security','Request rate limiting','pass','260 rapid requests to the login page: 237 served, 23 answered with 429 and a Retry-After header. One log entry was written for the whole burst.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (32,'SEC-007','2026-11-09','Security','Security response headers','pass','Content-Security-Policy with a per-request nonce, X-Frame-Options, X-Content-Type-Options, Referrer-Policy, Permissions-Policy and Cross-Origin-Opener-Policy are present; X-Powered-By is removed.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (33,'SEC-008','2026-11-09','Security','Third-party scripts and fonts','fixed','Tailwind and Google Fonts were loaded from external servers with no integrity check.','Both are now self-hosted; Google Translate is the only third-party script and only loads after consent.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (34,'SEC-009','2026-11-09','Security','Simultaneous payments on one invoice','info','Payments are recorded inside a transaction that locks the invoice row. Overpayment is rejected in sequential tests. A concurrent load test was not performed.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (35,'PRIV-001','2026-11-09','Privacy and compliance','Cookies and trackers inventory','pass','Before any choice the login page contacts no third-party host and sets one cookie (the session cookie, strictly necessary). No analytics, advertising or social trackers exist. Two interface preferences are kept in the browser.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (36,'PRIV-002','2026-11-09','Privacy and compliance','Consent before Google Translate','fixed','Choosing a language sent page text, including names and IP addresses, to Google without notice.','A consent notice appears first. Tested: no Google request before consent; Cancel resets the choice and sets no cookie; Allow translates and stores a timestamped record; the footer link withdraws consent and clears the cookie.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (37,'PRIV-003','2026-11-09','Privacy and compliance','Privacy requests: export and erasure','pass','The export downloads a JSON file with the account, sessions, log entries and invoices. Erasure without the confirmation box does nothing; with it the account is anonymised, sessions and IP addresses are removed, and invoices are kept for the legal retention period.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (38,'PRIV-004','2026-11-09','Privacy and compliance','Automatic retention','pass','A 13-month-old log entry and an 8-year-old invoice were inserted and the purge job removed both; newer records were kept.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (39,'PRIV-005','2026-11-09','Privacy and compliance','Privacy policy page','pass','The page contains all 11 sections copied from telecomlijn.nl, is reachable without logging in, and is linked from the login page and every admin page.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (40,'PRIV-006','2026-11-09','Privacy and compliance','HTTPS','open','The site runs on plain HTTP on localhost. The redirect to HTTPS, HSTS and secure cookies are in place but can only be verified once a certificate is installed on the real domain.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (41,'PRIV-007','2026-11-09','Privacy and compliance','Legal drafts and processor agreements','open','The processing register and breach procedure are drafts. They, the Google data-transfer basis, the processor agreements and the Cyberbeveiligingswet scope check need a lawyer or the responsible officer.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (42,'INV-001','2026-11-09','Invoices','List, filters and statuses','pass','Status chips, date range, search and column sorting work; overdue, due soon, open and paid invoices show the correct labels and balances.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (43,'INV-002','2026-11-09','Invoices','Creating an invoice','pass','An empty form lists the missing fields; entering lines updates the totals live (196,50 plus 41,27 BTW gives 237,77) and shows the due date.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (44,'INV-003','2026-11-09','Invoices','Recording payments','pass','An overpayment is rejected with the balance shown; 100,00 recorded as a partial payment; the remaining 137,77 marked the invoice as paid in full.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (45,'INV-004','2026-11-09','Invoices','Legal invoice content','fixed','Invoices lacked the supplier details, the customer address and the reason for a 0 percent BTW rate.','Added a supplier block (name, address, KvK, BTW-id, IBAN), a required customer address, a supply date and a required reason for 0 percent BTW.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (46,'INV-005','2026-11-09','Invoices','Real BTW number and IBAN','open','The supplier BTW number and IBAN are placeholders and every invoice shows a warning until they are entered in includes/company.php.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (47,'A11Y-001','2026-11-09','Accessibility','Automated scan (axe, WCAG 2.1 and 2.2 AA)','fixed','First scan: the rate-limit page had no language attribute, the overview statistics used invalid list markup, and the disabled Previous button had a contrast ratio of 3.68:1.','Added the language attribute, rebuilt the markup, and made the disabled button readable. The final scan of the overview, tables, invoices, settings tabs, privacy page, creator page and password page found no violations.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (48,'A11Y-002','2026-11-09','Accessibility','Manual accessibility checks','open','Screen-reader use, 200 percent zoom and reflow, and full keyboard walkthroughs were not tested. Automated tools find only part of the issues.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (49,'INT-001','2026-11-09','Integrations','Real health checks','pass','Checks against telecomlijn.nl and example.com returned up with HTTP 200 in about 270 to 290 ms and were stored with history and uptime.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (50,'INT-002','2026-11-09','Integrations','Server-side request forgery (internal targets)','fixed','Twenty-one hostile addresses were tried (localhost, private ranges, cloud metadata, file and ftp schemes, odd ports, credentials in the URL, numeric and IPv6 forms). All were blocked, but three defects surfaced: an unresolvable host name crashed validation (failed safe), the IPv6 form [0:0:0:0:0:ffff:7f00:1] for 127.0.0.1 was allowed, and carrier-grade NAT, multicast, documentation and Teredo ranges were not covered.','Validation now parses the binary address and checks every embedded IPv4 address, adds an explicit deny-list, and treats unresolvable names as a normal error. Final test: 23 internal forms blocked, 7 public forms allowed.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (51,'INT-003','2026-11-09','Integrations','Redirects, timeouts and certificates','pass','A redirect is reported (HTTP 301) and never followed; a non-routable address times out with a clear message; an expired TLS certificate is reported as a certificate problem.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (52,'INT-004','2026-11-09','Integrations','Secrets and markup in endpoint data','pass','A stored secret header is encrypted in the database and never shown again; an endpoint name containing script markup is displayed as escaped text.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (53,'INT-005','2026-11-09','Integrations','Scheduled checks','open','check_endpoints.php passes the syntax check but was not run from Windows Task Scheduler. Checks currently run when someone presses Check now.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (54,'API-001','2026-11-09','Health API','Authentication of the inbound API','pass','No key, a wrong key and a revoked key return 401; a key in the URL is refused; POST returns 405; a valid key returns JSON with no cookie and no endpoint addresses.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (55,'API-002','2026-11-09','Health API','Key handling and throttling','pass','The key is shown once at creation and is stored only as a hash. Revoking works at once. After six failed attempts further failures return 429, and the first failure is logged.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (56,'DEMO-001','2026-11-09','Demo data','Load and remove demo data without touching real data','pass','With a real invoice, endpoint, backup, report and user present, loading added 72 users, 48 invoices and the rest, all tagged as demo. Removing deleted exactly the tagged records (760) and every real record survived. A demo invoice that received a real payment was kept on purpose.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (57,'DEMO-002','2026-11-09','Demo data','Security of the demo-data buttons','pass','A request without a token is 403; removal without the confirmation field does nothing; a normal user gets 403 for both actions; loading twice is refused; opening the endpoint with GET just redirects.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (58,'DEMO-003','2026-11-09','Demo data','Overview buttons in the browser','pass','Clicking Load demo data took about 4 seconds and showed a summary; the panel then offered a confirmed Remove; after removal the panel offered Load again.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (59,'DATA-001','2026-11-09','Data and setup','Reset script safety','pass','Running setup.php on an existing database is refused unless --reset is given, because it deletes everything.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (60,'DATA-002','2026-11-09','Data and setup','System with no data at all','pass','After the reset every data table had zero rows except the admin account; all 14 pages loaded without errors and showed sensible empty states.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:21:05');
INSERT INTO `test_log` VALUES (123,'UI-010','2026-11-09','Interface','Easter egg: typing \"Teletollie\" in the search bar','pass','The button appears for \"Teletollie\" and for \" Teletollie \" (surrounding spaces are ignored) but not for \"teletollie\", \"TELETOLLIE\", \"TeleTollie\", \"Teletollies\" or \"Teletoll\", so it cannot appear by accident. The creator easter egg still works. Enter moves focus to the button; the page shows the supplied definition and example with one heading and a Dutch language marker (the status tag was later changed from Not published to A Broken Dream at the owner request); logged-out visitors are redirected to the login page.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:23:48');
INSERT INTO `test_log` VALUES (124,'TEST-001','2026-11-09','Test log','Who can open the Tests tab','pass','Admins see the tab. A normal user, even with the Can manage integrations permission, sees no link and gets 403 for the tab, for a forged add request and for the CSV export, and no entry was created.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:23:48');
INSERT INTO `test_log` VALUES (125,'TEST-002','2026-11-09','Test log','Baseline import','pass','The documented baseline (60 entries) was imported on the first view. Opening the tab several more times created no duplicates.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:23:48');
INSERT INTO `test_log` VALUES (126,'TEST-003','2026-11-09','Test log','Filters, search and safe output','pass','Result and area filters and the search return the expected rows and counts. A search containing SQL-looking text and array-style parameters are handled without errors. Markup typed into an entry is displayed as escaped text.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:23:48');
INSERT INTO `test_log` VALUES (127,'TEST-004','2026-11-09','Test log','Adding and deleting entries','fixed','The first attempt to add an entry returned a 500 error because the date-checking helper was not loaded on this tab (found in the error log). After the fix an empty entry is rejected, a valid entry is saved under the signed-in person, deleting a baseline entry is refused, and a request without a token returns 403.','The tab now loads the shared date helper.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:23:48');
INSERT INTO `test_log` VALUES (128,'TEST-005','2026-11-09','Test log','CSV export','pass','The download has the correct headers and one row per entry, supports the active filters, and opens cleanly in a spreadsheet. Cells starting with =, + or @ are neutralised with an apostrophe so they cannot run as formulas. Exports, additions and deletions appear in the activity log.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:23:48');
INSERT INTO `test_log` VALUES (195,'KUMA-001','2026-11-09','Uptime Kuma','Metrics parser against a sample /metrics payload','pass','A fixture with six monitors (http, ping, port) parses correctly: statuses 1/0/2/3 map to up/down/pending/maintenance, response time -1 and NaN become empty, certificate days and validity are read, names containing quotes and braces survive, a trailing timestamp is accepted, unrelated metrics are ignored, monitors are sorted with down first, and malformed or empty input never causes an error.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (196,'KUMA-002','2026-11-09','Uptime Kuma','Encryption of the API key at rest','pass','AES-256-GCM round trip returns the key; the ciphertext never contains it; every encryption differs; tampering or the wrong key is rejected; a missing encryption key fails loudly instead of storing plain text. The existing application key is reused.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (197,'KUMA-003','2026-11-09','Uptime Kuma','Address validation and request safety','pass','http and https only, no credentials, query or fragment in the address, port range checked. Internal and loopback addresses are allowed because Kuma normally runs internally, while link-local (cloud metadata), unspecified and multicast addresses are refused. The connection is pinned to the validated address, redirects are not followed, the wait is 5 seconds and the response is limited in size.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (198,'KUMA-004','2026-11-09','Uptime Kuma','Settings access and secrecy of the key','pass','Signed-out requests get 401. A normal user gets 403 on the endpoints and the tab and does not see the tab in the menu, even with other permissions. A missing or wrong CSRF token is 403. The GET response contains exactly four fields and never the key; the page shows only a masked placeholder; the stored value is ciphertext. A blank key keeps the stored ciphertext unchanged; a typed key replaces it; a failed form never echoes a typed key; the log never contains the key.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (199,'KUMA-005','2026-11-09','Uptime Kuma','Test connection outcomes','pass','Valid key: success with the monitor count. Bad key: unauthorized. HTML answer: invalid response. Server error, closed port and a slow server that exceeds the time limit: unreachable, without passing on upstream error text. Invalid addresses and the metadata address are refused before any request. Testing never changes the saved settings.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (200,'KUMA-006','2026-11-09','Uptime Kuma','Monitoring service: states and caching','fixed','Not configured, up to date, unauthorized, unreachable and invalid-response states all behave, and the last good data is returned flagged stale instead of a crash. Ten dashboard requests reach Kuma once; failures are cached too so a down Kuma is not hammered; saving settings clears the cache. One defect: the monitor fields were not in the documented order.','The fields are now produced in the documented order.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (201,'KUMA-007','2026-11-09','Uptime Kuma','Uptime page loads','fixed','The automated suite found that the Uptime page crashed with a 500 error, because it used a constant defined in a file it had not loaded.','The page now loads the Kuma module. Retested: the page loads and polls only the dashboard backend.','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (202,'KUMA-008','2026-11-09','Uptime Kuma','Settings tab and Uptime page in the browser','pass','Empty state with a button to the settings tab; saving shows a confirmation and a masked key; invalid input shows messages under the right fields; Test connection shows the result inline; summary tiles, down-first table, certificate warnings (expired, expires in 9 days) and the stale banner when Kuma goes down all render; no console errors; no accessibility violations in the automated scan; no horizontal scrolling on a phone.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (203,'KUMA-009','2026-11-09','Uptime Kuma','Automated test suite','info','tests/run.php (166 checks, no framework) covers the parser, encryption, address validation, the monitoring states and caching, the history and uptime calculations, the settings endpoints, the monitoring endpoints and the saved health-API keys, using a mock Kuma on port 3199. Run it with php tests/run.php while Apache and MariaDB are running. It backs up and restores the saved Kuma settings.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (204,'KUMA-010','2026-11-09','Uptime Kuma','Against a real Uptime Kuma server','open','Everything was tested against a mock that reproduces the documented metrics format and the Basic-auth rule. It has not yet been run against your real Kuma. Save its address and API key, press Test connection, and check the Uptime page.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:41:33');
INSERT INTO `test_log` VALUES (281,'KUMA-011','2026-11-09','Uptime Kuma','History: heartbeats, uptime percentages and events','pass','Each monitor has a stable id. The first fetch records one heartbeat per monitor; a second fetch within a minute with no change records nothing; a status change is recorded at once and marked important; after a minute every monitor gets a new heartbeat. On synthetic history the 24-hour uptime (3 of 4 counted checks, maintenance excluded) and 30-day uptime (5 of 8) and the 24-hour average response (up checks only) are exact, a monitor with no history shows empty rather than 0 percent, and the list view receives the newest 40 heartbeats oldest-first. Detail and events endpoints require a sign-in, reject malformed or hostile ids, and never contain the key. History is deleted after 30 days.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:52:14');
INSERT INTO `test_log` VALUES (282,'KUMA-012','2026-11-09','Uptime Kuma','Kuma-style Uptime page in the browser','pass','Kuma layout in the dashboard own colours (navy panels, lime for up, coral for down, butter for pending, rounded cards and chip-style filter tabs) instead of Kuma black palette. Monitor list with search and Up/Down/Pending/Maintenance filter tabs, Quick Stats and recent status changes on the dashboard view, and a detail view with the status badge, heartbeat bar, response time, 24-hour and 30-day uptime, certificate expiry, a 24-hour response chart with down periods marked, and an important-heartbeats table. Selecting a monitor is kept in the address, so reload and the back button work. Filtering by Down and searching for sip return the right monitors; no console errors, no content-policy violations, no accessibility violations, and no horizontal scrolling on a phone.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:52:14');
INSERT INTO `test_log` VALUES (283,'UI-011','2026-11-09','Interface','LinkedIn button on the creator page','pass','The creator page has a Connect on LinkedIn button that opens the supplied profile in a new tab with rel noopener noreferrer, and a hidden note for screen readers that it opens in a new tab.','','Claude Code with Denis Mehmed','baseline','2026-11-09 14:52:14');
INSERT INTO `test_log` VALUES (363,'KEYS-001','2026-11-09','Saved keys','Health-API keys can be shown again','fixed','A key used to be displayed once, at creation, and was gone after a refresh, so a new key had to be made every time. Keys are now stored encrypted as well as hashed. Tested: a new key is encrypted in the database; Show key returns the exact key that incoming calls are checked against and it works against the health API; after a page refresh and after a completely new sign-in the same key is shown again; the full key is never written into the page; responses are not cached; every reveal is logged with the key name only. Permissions: Can manage may show keys, view-only and no-access users get 403 and no button, signed-out is 401, a wrong token is 403. Revoked keys can not be shown and stop working at once. Keys made before this change can not be recovered and say so.','Added encrypted storage (key_enc), the Show key, Hide key and Copy buttons (the key hides itself after 30 seconds), and api_key_reveal.php.','Claude Code with Denis Mehmed','baseline','2026-11-09 15:05:50');
INSERT INTO `test_log` VALUES (364,'KEYS-002','2026-11-09','Saved keys','Saved keys survive a database reset','fixed','Running setup.php --reset dropped the whole database, so a saved Kuma connection, API keys and endpoints were lost, and a new encryption key would have made any kept secrets unreadable. Tested with a real reset on a backed-up database: the Kuma connection, health-API keys, own endpoints and manual test-log entries were kept, the encryption key was reused so the kept key still decrypted to the original and still matched its hash, and --wipe-all removed everything and created a new encryption key. The database was then restored from the backup.','A reset now keeps those four things and the encryption key; --wipe-all deletes them too.','Claude Code with Denis Mehmed','baseline','2026-11-09 15:05:50');
INSERT INTO `test_log` VALUES (365,'KEYS-003','2026-11-09','Saved keys','The saved Kuma API key persists across refreshes','pass','In the browser, after saving a Kuma address and key, three page refreshes in a row still showed the address and the masked key (••••••••WXYZ) with \"A key is saved\". The key is stored encrypted and is deliberately never sent back to the page, so it can be replaced but not displayed.','','Claude Code with Denis Mehmed','baseline','2026-11-09 15:05:50');
INSERT INTO `test_log` VALUES (366,'KEYS-004','2026-11-09','Saved keys','Development clean-up removed saved settings','info','While building and testing, some manual clean-up commands emptied the saved Kuma settings, the Uptime history and the activity log. A Kuma key saved during that time had to be entered again. The automated suite restores saved settings after it runs and only deletes rows it created, and the reset script now keeps connection settings.','','Claude Code with Denis Mehmed','baseline','2026-11-09 15:05:50');
INSERT INTO `test_log` VALUES (450,'AUDIT-001','2026-11-09','Full-site audit','Whole-site crawl at phone, tablet and desktop width','fixed','Crawled 31 pages at 360, 768 and 1440 px, checking horizontal overflow, broken images, duplicate ids, heading count, empty links, leaked PHP errors, console errors, failed requests, every internal link and accessibility (axe, WCAG 2.2 AA). Only layout problems were found: the Overview grid, the Tests table, the Privacybeleid grid and a long address on Integrations pushed the page wider than the screen on small widths.','Grid children may now shrink (min-width 0), scrolling tables keep their hidden text inside the scroller, and long addresses wrap. Re-crawled: no overflow, no broken links, no console or page errors.','Claude Code with Denis Mehmed','baseline','2026-11-09 15:39:09');
INSERT INTO `test_log` VALUES (451,'AUDIT-002','2026-11-09','Full-site audit','Click-through of every control','pass','87 interactions: every sidebar link, every sort header, filter and pagination link on the table pages, searches, the invoice date filter, suspend a user, end a session, start a backup, generate and download a report, record a payment, open the Tests form, both easter eggs, the language consent panel and the sidebar edge. All worked and no error text appeared.','','Claude Code with Denis Mehmed','baseline','2026-11-09 15:39:09');
INSERT INTO `test_log` VALUES (452,'MOTION-001','2026-11-09','Animation','Motion system rebuilt on real spring curves','pass','Easing is now a damped spring (CSS linear(), 8% and 16% overshoot) with a cubic-bezier fallback. Panels arrive in reading order with children following through, bars squash and stretch, buttons wind down on press and spring back, the sidebar pill squashes and stretches as it travels between items, the sidebar and its items follow through when it pops out, rows pull back before they leave, toasts arrive on an arc and show a countdown, status dots breathe, the header gains a shadow on scroll, cards have a light that follows the cursor and disclosure panels open with a spring. Measured in a real browser: the sidebar reaches the edge in about 0.4 s, overshoots by about 6% and settles by 1.2 s; the pill is squashed mid-move and returns to exactly its resting size.','','Claude Code with Denis Mehmed','baseline','2026-11-09 15:39:09');
INSERT INTO `test_log` VALUES (453,'MOTION-002','2026-11-09','Animation','Reduced-motion preference respected','pass','With the system setting for reduced motion, entrances, loops, shimmer and the cursor light are turned off and the page appears at once; colour and state changes still show. Page transitions are disabled.','','Claude Code with Denis Mehmed','baseline','2026-11-09 15:39:09');
